/bin/bash -lc "./bin/ffmpeg -hide_banner -i materials/match.m4a -f null - 2>&1 | sed -n '1,80p'
command -v whisper || true
command -v python
python - <<'PY'
mods=['librosa','scipy','soundfile','torch','whisper','faster_whisper','speech_recognition']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',type(e).__name__)
PY"

